def active_sessions(records, now):
    return [r for r in records if not r.get('expires_at') or r['expires_at'] >= now]

def active_tokens(records, now):
    return [r for r in records if not r.get('expires_at') or r['expires_at'] >= now]

def clone_profiles(records):
    return [dict(r) for r in records]

def clone_policies(records):
    return [dict(r) for r in records]

def normalize_users(records):
    return {key.strip().lower(): value for key, value in records}

def normalize_groups(records):
    return {key.strip().lower(): value for key, value in records}

